#!/usr/bin/env python3
"""统计 CSV 文件每一列的非空值数量。

用法:
    python count_csv_nonempty.py data.csv
    python count_csv_nonempty.py data.csv --delimit-whitespace
"""

import argparse
import csv
import sys


def count_nonempty(path, encoding="utf-8-sig", strict_whitespace=False):
    with open(path, newline="", encoding=encoding) as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return [], {}

        counts = {name: 0 for name in header}
        for row in reader:
            for i, cell in enumerate(row):
                if i >= len(header):
                    continue
                value = cell if strict_whitespace else cell.strip()
                if value != "":
                    counts[header[i]] += 1
        return header, counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每列非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    parser.add_argument("--encoding", default="utf-8-sig", help="文件编码, 默认 utf-8-sig")
    parser.add_argument(
        "--strict-whitespace",
        action="store_true",
        help="不把纯空白单元格视为空(默认 strip 后为空即算空)",
    )
    args = parser.parse_args()

    try:
        header, counts = count_nonempty(args.csv_file, args.encoding, args.strict_whitespace)
    except FileNotFoundError:
        sys.exit(f"文件不存在: {args.csv_file}")

    if not header:
        print("文件为空，没有可统计的列。")
        return

    width = max(len(name) for name in header)
    for name in header:
        print(f"{name:<{width}}  {counts[name]}")


if __name__ == "__main__":
    main()
